import AsyncStorage from '@react-native-async-storage/async-storage';

const BASE_URL = process.env.EXPO_PUBLIC_API_URL || 'https://api.qurac.com/v1';

const getHeaders = async () => {
  const token = await AsyncStorage.getItem('userToken');
  return {
    'Content-Type': 'application/json',
    'Authorization': token ? `Bearer ${token}` : '',
  };
};

export const ApiService = {
  // Fetch Patients List (Currently fallback to mock data)
  getPatients: async () => {
    try {
      const headers = await getHeaders();
      const response = await fetch(`${BASE_URL}/patients`, { headers });
      if (!response.ok) throw new Error('API request failed');
      return await response.json();
    } catch (error) {
      console.log('Using local mock state until backend is connected');
      return null;
    }
  },

  // Fetch Full Patient Medical Record
  getPatientDetails: async (patientId: string) => {
    try {
      const headers = await getHeaders();
      const response = await fetch(`${BASE_URL}/patients/${patientId}/full-profile`, { headers });
      return await response.json();
    } catch (error) {
      console.log('Using static profile data');
      return null;
    }
  },
};q                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             